-- Recalculate current_balance for all 5 accounts from posted journal lines
UPDATE accounts a
   SET current_balance = COALESCE((
     SELECT SUM(jl.debit_amount - jl.credit_amount)
       FROM journal_lines jl
       JOIN journal_entries je ON je.id = jl.journal_entry_id
      WHERE jl.account_id = a.id
        AND je.is_posted = true
   ), 0)
 WHERE a.id IN ('a68da106-bae6-43d4-9c59-faaaae108f7e','68c67428-5bca-4255-b931-6e00d688a1db','fa469f28-35cc-414c-90f8-359aa52e149b','4818ad83-204a-43ca-9b95-8e504fcef547','19a014e4-72a4-4bc2-89fd-00389055fdb3');

-- Show updated balances
SELECT account_code, account_name, current_balance
  FROM accounts
 WHERE id IN ('a68da106-bae6-43d4-9c59-faaaae108f7e','68c67428-5bca-4255-b931-6e00d688a1db','fa469f28-35cc-414c-90f8-359aa52e149b','4818ad83-204a-43ca-9b95-8e504fcef547','19a014e4-72a4-4bc2-89fd-00389055fdb3')
 ORDER BY account_code;

-- Review the output of the SELECTs above. If the "still_on_11000_should_be_zero" is 0
-- and the balances look correct, run:  COMMIT;
-- Otherwise run:                       ROLLBACK;
